// Worker entry: OpenNext's generated handler for HTTP, plus a Cron Trigger handler.
// `wrangler.jsonc` points "main" here; `opennextjs-cloudflare build` must run first so that
// .open-next/worker.js exists.

// ts-ignore, not ts-expect-error: the file only exists after a build, so the error comes and goes.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore: generated by `opennextjs-cloudflare build`
import { default as handler } from "../.open-next/worker.js";

export default {
  fetch: handler.fetch,

  // Cron Trigger (see "triggers" in wrangler.jsonc). Runs the new-episodes job by sending the
  // same authenticated request any external scheduler would, through the app's own fetch handler,
  // so the route's auth, logging and error handling all apply. No network hop, no public URL needed.
  async scheduled(controller: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    if (!env.CRON_SECRET) {
      console.error("CRON_SECRET is not set; skipping the new-episodes job");
      return;
    }
    const request = new Request("https://otakuvault.internal/api/jobs/new-episodes", {
      method: "POST",
      headers: { Authorization: `Bearer ${env.CRON_SECRET}` },
    });
    const res: Response = await handler.fetch(request, env, ctx);
    const body = await res.text();
    if (!res.ok) throw new Error(`new-episodes job (${controller.cron}) failed: ${res.status} ${body}`);
    console.log(`new-episodes job (${controller.cron}): ${body}`);
  },
} satisfies ExportedHandler<CloudflareEnv>;

// Durable Object classes OpenNext's caching uses must be exported from the entry module.
// ts-ignore, not ts-expect-error: the file only exists after a build, so the error comes and goes.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore: generated by `opennextjs-cloudflare build`
export { DOQueueHandler } from "../.open-next/worker.js";
